-- TAX_RETURN, a new document type: a filed tax return of a year, either a
-- Modello 730 or a Modello Redditi Persone Fisiche (Redditi PF). The 730
-- area reads its figures (quadri RN, RV, RX of the Redditi PF, the 730-3 of
-- the 730): they replace the year's forecast, are compared with it, and mark
-- the year's filing deadline as done in the Agenda.
-- A category with the same id is kept as it is. When one of your own already
-- has the title "Tax return", this one is added as "Tax return (730, Redditi
-- PF)" instead of being skipped (titles are unique).
-- Data only. Rollback: drizzle/rollback/0029_tax_return_category.down.sql.
WITH inserted AS (
  INSERT INTO "ingestion"."document_categories" ("id", "title", "description", "template_json", "dimension")
  SELECT 'TAX_RETURN',
         CASE WHEN EXISTS (SELECT 1 FROM "ingestion"."document_categories" WHERE lower("title") = 'tax return')
              THEN 'Tax return (730, Redditi PF)' ELSE 'Tax return' END,
         'A filed Italian tax return (dichiarazione dei redditi): a Modello 730 or a Modello Redditi Persone Fisiche (Redditi PF, once Unico), as downloaded from the Agenzia delle Entrate site or given by the CAF or commercialista. Not the precompilata draft, not an F24, not the ricevuta di trasmissione alone. The 730 area reads its figures and marks the year''s filing as done.',
         '{"fields": [{"key": "form_type", "label": "Form", "type": "enum", "description": "Which return it is: 730 for a Modello 730 (with its 730-3 prospetto di liquidazione), redditi_pf for a Modello Redditi Persone Fisiche (REDDITI PF, once Unico, quadri RN, RV, RX)", "required": true, "options": ["730", "redditi_pf"]}, {"key": "tax_year", "label": "Tax year", "type": "integer", "description": "Periodo d''imposta: the year the income is about (PERIODO D''IMPOSTA 2025 is 2025), not the year in the form''s name (Redditi 2026, 730/2026)", "required": true}, {"key": "filed_on", "label": "Filed on", "type": "date", "description": "Data di presentazione, or the date after \"del\" in the identificativo dichiarazione (del 18/9/2026)", "required": false}, {"key": "filing_id", "label": "Filing number", "type": "string", "description": "Identificativo dichiarazione or protocollo telematico, as printed", "required": false}, {"key": "return_kind", "label": "Kind", "type": "enum", "description": "ordinary for the first return of the year; correction for a dichiarazione correttiva nei termini; supplementary for a dichiarazione integrativa", "required": false, "options": ["ordinary", "correction", "supplementary"]}, {"key": "employment_income", "label": "Employment income", "type": "amount", "description": "Redditi di lavoro dipendente: quadro RC TOTALE (Redditi PF) or quadro C (730)", "required": false}, {"key": "total_income", "label": "Total income", "type": "amount", "description": "Reddito complessivo: rigo RN1, its last column REDDITO COMPLESSIVO (not column 1, the reddito di riferimento per agevolazioni fiscali), or the 730-3 reddito complessivo", "required": false}, {"key": "main_home_deduction", "label": "Main home deduction", "type": "amount", "description": "Deduzione per abitazione principale: rigo RN2, or the same line of the 730-3", "required": false}, {"key": "deductible_expenses", "label": "Deductible charges", "type": "amount", "description": "Oneri deducibili: rigo RN3, or the 730-3 oneri deducibili", "required": false}, {"key": "taxable_income", "label": "Taxable income", "type": "amount", "description": "Reddito imponibile: rigo RN4, or the 730-3 reddito imponibile", "required": false}, {"key": "gross_tax", "label": "Gross tax", "type": "amount", "description": "Imposta lorda: rigo RN5, or the 730-3 imposta lorda", "required": false}, {"key": "work_family_deductions", "label": "Employment and family tax credits", "type": "amount", "description": "Totale detrazioni per carichi di famiglia e lavoro: rigo RN8, or the sum of the family and employment detrazioni of the 730-3", "required": false}, {"key": "expense_deductions_19", "label": "19% expense credits", "type": "amount", "description": "Detrazione oneri (quadro RP section I, 730 section E-I): rigo RN13", "required": false}, {"key": "renovation_deductions", "label": "Building bonus credits", "type": "amount", "description": "Detrazione spese per interventi di recupero del patrimonio edilizio (quadro RP section III-A, 730 section E-III): rigo RN14", "required": false}, {"key": "other_home_deductions", "label": "Furniture and other home credits", "type": "amount", "description": "Detrazione spese quadro RP section III-C (bonus mobili, arredo, IVA abitazione), 730 section E-III C: rigo RN15", "required": false}, {"key": "energy_deductions", "label": "Energy efficiency credits", "type": "amount", "description": "Detrazione spese per risparmio energetico (quadro RP section IV, 730 section E-IV): rigo RN16", "required": false}, {"key": "total_deductions", "label": "Total tax credits", "type": "amount", "description": "Totale detrazioni d''imposta: rigo RN22, or the 730-3 totale detrazioni", "required": false}, {"key": "net_tax", "label": "Net tax", "type": "amount", "description": "Imposta netta: rigo RN26, or the 730-3 imposta netta", "required": false}, {"key": "irpef_withheld", "label": "IRPEF withheld", "type": "amount", "description": "Ritenute totali: rigo RN33 column 4, or the 730-3 ritenute", "required": false}, {"key": "advances_paid", "label": "Advances paid", "type": "amount", "description": "Acconti versati: rigo RN38 column 6, or the 730-3 acconti", "required": false}, {"key": "irpef_due", "label": "IRPEF to pay", "type": "amount", "description": "IRPEF a debito: rigo RX1 column 1 (RN45), or the 730-3 IRPEF a debito (saldo)", "required": false}, {"key": "irpef_credit", "label": "IRPEF credit", "type": "amount", "description": "IRPEF a credito: rigo RX1 column 2 (RN46), or the 730-3 IRPEF a credito (rimborso)", "required": false}, {"key": "regional_surtax_due", "label": "Regional surtax to pay", "type": "amount", "description": "Addizionale regionale a debito: rigo RX2 column 1 (RV7)", "required": false}, {"key": "regional_surtax_credit", "label": "Regional surtax credit", "type": "amount", "description": "Addizionale regionale a credito: rigo RX2 column 2 (RV8)", "required": false}, {"key": "municipal_surtax_due", "label": "Municipal surtax to pay", "type": "amount", "description": "Addizionale comunale a debito: rigo RX3 column 1 (RV15)", "required": false}, {"key": "municipal_surtax_credit", "label": "Municipal surtax credit", "type": "amount", "description": "Addizionale comunale a credito: rigo RX3 column 2 (RV16)", "required": false}, {"key": "next_advance_first", "label": "First advance for next year", "type": "amount", "description": "Primo acconto IRPEF dovuto: rigo RN62 column 1, or the 730-3 primo acconto", "required": false}, {"key": "next_advance_second", "label": "Second advance for next year", "type": "amount", "description": "Secondo o unico acconto IRPEF dovuto: rigo RN62 column 2, or the 730-3 secondo acconto", "required": false}, {"key": "health_expenses", "label": "Health expenses", "type": "amount", "description": "Spese sanitarie: rigo RP1 column 2, or rigo E1 of the 730", "required": false}]}'::jsonb,
         'DOCUMENT_TYPE'
  ON CONFLICT DO NOTHING
  RETURNING "id", "title", "parent_id", "dimension"
)
-- Modules that keep their own copy of the categories (review inbox, the 730…) learn it from category.changed@1.
INSERT INTO "ingestion"."outbox" (event_type, payload)
SELECT 'category.changed@1',
       jsonb_build_object(
         'id', i.id,
         'title', i.title,
         'parentId', i.parent_id,
         'dimension', i.dimension,
         'deleted', false,
         'changedAt', to_char(now() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
       )
  FROM inserted i;
